#include <rclcpp/rclcpp.hpp>
#include <sensor_msgs/msg/joy.hpp>
class Ground:public rclcpp::Node{public:Ground():Node("manual_take_over_ground_station"){pub_=create_publisher<sensor_msgs::msg::Joy>("/joystick_from_users",10);sub_=create_subscription<sensor_msgs::msg::Joy>("/joy",10,[this](auto m){if(m->buttons.size()>3&&(m->buttons[0]||m->buttons[1]||m->buttons[2]||m->buttons[3]))stop_=true;if(stop_)pub_->publish(*m);});}private:bool stop_=false;rclcpp::Subscription<sensor_msgs::msg::Joy>::SharedPtr sub_;rclcpp::Publisher<sensor_msgs::msg::Joy>::SharedPtr pub_;};int main(int c,char**v){rclcpp::init(c,v);rclcpp::spin(std::make_shared<Ground>());rclcpp::shutdown();}
